                    case 29:
                        ScbTable.CheckColumn(column, "Character.SpecialSkill4", ScbTable.KindScalar, 1, ScbTable.ElementI32, ScbTable.ElementVarint);
                        cursor = new ScbColumnCursor(reader, column, count, "Character.SpecialSkill4");
